    expect(calc.computeShippingCents([makeLine("a", 100)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets array", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with upToGrams <= 0", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 50 }], -1),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const line: CartLine = {
      product: { id: "a", name: "A", unitPriceCents: 100 },
      quantity: 2,
    };
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([line], 5000)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 400g → bracket 500
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    // 500g → bracket 500 (boundary, inclusive)
    expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    // 501g → bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    // 1000g → bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 1000)], 1000)).toBe(600);
    // 1500g → bracket 2000
    expect(calc.computeShippingCents([makeLine("a", 1500)], 1000)).toBe(900);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500)], 1000)).toBe(1200);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 700)], 1000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200*2 + 300*1 = 700g → bracket 1000
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart - line management", () => {
  it("add() inserts a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantity for the same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects quantity <= 0", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove() deletes a line and returns true", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("z", 1)).toThrow("Product z is not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("computes subtotal from unit price * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3); // 3 * 1000 = 3000
    cart.add(productB, 2); // 2 * 2500 = 5000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(8000);
  });

  it("applies discount policy", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 2); // subtotal = 2000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1000);

    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart2 = new Cart({ discountPolicy: negDiscount });
    cart2.add(productA, 1);
    expect(cart2.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 1); // subtotal = 1000, discount = 200, discounted = 800
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("shipping receives discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(productA, 2); // subtotal = 2000, discount = 300, discounted = 1700
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1700,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 72 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 599 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal=1000, disc=100, discounted=900, tax=72, ship=599
    const totals = cart.totals();
    expect(totals.totalCents).toBe(900 + 72 + 599);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses custom region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = { computeTaxCents: () => -50 };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = { computeShippingCents: () => -100 };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

