import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines snapshot", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("with priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow("service down");
    });
  });

  describe("with inventoryChecker", () => {
    it("passes when available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when not available", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("first denial wins with multiple items", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });
  });

  describe("with asyncTaxProvider", () => {
    it("uses async tax rate instead of sync calculator", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 1); // subtotal = 1000
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 200 },
        region: "US",
      });
      cart.add(productA, 1); // subtotal=1000, disc=200, discounted=800
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.taxCents).toBe(80); // 10% of 800
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline", () => {
    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 500 },
        shippingCalculator: { computeShippingCents: () => 300 },
        region: "US",
      });
      cart.add(productA, 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const taxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: taxProvider,
      });

      // refreshed subtotal: 2 * 2000 = 4000
      // discount: 500, discounted: 3500
      // tax: 5% of 3500 = 175
      // shipping: 300
      // total: 3500 + 175 + 300 = 3975
      expect(result.totals.subtotalCents).toBe(4000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(175);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(3975);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% correctly", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.00 → 33
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(99999999)).toBe(Math.floor(99999999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts zero amount", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });

  it("returns discount when subtotal exceeds amount", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(10000)).toBe(500);
  });

  it("clamps to subtotal when amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(5000);
    expect(policy.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, plus 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy sees the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both get 50% of 1000 = 500 each → 1000 total
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative individual discounts to 0 before summing", () => {
      const negPolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negPolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // max(0, -100) + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining = 9000
      // Second: 10% of 9000 = 900
      // total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // A: fixed 500, remaining 9500, then 10% of 9500 = 950, total = 1450
      // B: 10% of 10000 = 1000, remaining 9000, then min(500, 9000)=500, total = 1500
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("clamps each step to remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200
      // total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(5000)).toBe(300);
  });
});

