import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (id: string, weightGrams: number, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([makeLine("a", 100)], 2000)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when subtotal >= freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal < freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(599);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 100)], 1000)).toBe(0);
  });

  it("accepts 0 freeOverCents (always free for non-negative subtotals)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([makeLine("a", 100)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets array", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with upToGrams <= 0", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 50 }], -1),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const line: CartLine = {
      product: { id: "a", name: "A", unitPriceCents: 100 },
      quantity: 2,
    };
    const calc = new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 500 }]);
    expect(calc.computeShippingCents([line], 5000)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 400g → bracket 500
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    // 500g → bracket 500 (boundary, inclusive)
    expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    // 501g → bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    // 1000g → bracket 1000
    expect(calc.computeShippingCents([makeLine("a", 1000)], 1000)).toBe(600);
    // 1500g → bracket 2000
    expect(calc.computeShippingCents([makeLine("a", 1500)], 1000)).toBe(900);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500)], 1000)).toBe(1200);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(600);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 700)], 1000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200*2 + 300*1 = 700g → bracket 1000
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
  });
});

